      { auteur: "Ibn Ḥabīb (d'après Ibn Rāshid et at-Tawḍīḥ)", avis: "Il est obligatoire quand on s'en souvient.", statut: "qawl" },
      { auteur: "Ibn Ḥabīb (d'après adh-Dhakhīra) ; al-Lakhmī (interprétation de la Mudawwana)", avis: "Il est recommandé.", statut: "qawl" }
